// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Set owner to caller
        vm.prank(c.owner());
        c.transferOwnership(caller);
        // Now caller is owner, call owned()
        vm.prank(caller);
        c.owned();
        // After owned(), owner should still be caller (owned() does nothing with onlyOwner modifer)
        assertTrue(c.owner() == caller);
    }
}

